// ABOUTME: Property tests for the assessment engine, generated by a seeded fast-check run so a
// ABOUTME: failure reproduces: totals stay within the maximum, mark order is irrelevant, scaling is
// ABOUTME: monotonic, the result is deterministic, and every trace replays into its own numbers.

import * as fc from 'fast-check';
import { describe, expect, it } from 'vitest';

import { compareExact, formatExact, parseExact, type Exact } from '../exact';
import { evaluateScheme, replaySchemeTrace } from '../index';
import type { MarkStatus, SchemeDefinition, SchemeEvaluationInput, SchemeMark, SchemeResult } from '../index';

const OPTIONS = { seed: 20261021, numRuns: 150 } as const;

function decimalAt(value: number, scale: number): string {
  const sign = value < 0 ? '-' : '';
  const digits = String(Math.abs(value)).padStart(scale + 1, '0');
  const split = digits.length - scale;
  return scale === 0 ? `${sign}${digits}` : `${sign}${digits.slice(0, split)}.${digits.slice(split)}`;
}

const hundredths = (value: number): string => decimalAt(value, 2);

function scoreOf(max: number): fc.Arbitrary<string> {
  return fc.integer({ min: 0, max: Math.round(max * 100) }).map(hundredths);
}

function mustExact(text: string | null): Exact {
  if (text === null) throw new Error('expected a value');
  const value = parseExact(text);
  if (value === null) throw new Error(`not an exact value: ${text}`);
  return value;
}

function resultOf(input: SchemeEvaluationInput): SchemeResult {
  const evaluation = evaluateScheme(input);
  if (!evaluation.ok) throw new Error(`unexpected issues: ${evaluation.issues.map((issue) => issue.code).join(', ')}`);
  return evaluation.result;
}

function totalOf(result: SchemeResult): Exact {
  return mustExact(result.total);
}

const ngScheme: SchemeDefinition = {
  code: 'ng-terminal',
  slots: [
    { code: 'CA1', max: '20' },
    { code: 'CA2', max: '20' },
    { code: 'EXAM', max: '60' },
  ],
  learning_area_score: { op: 'sum', of: ['CA1', 'CA2', 'EXAM'], out_of: '100' },
  missing: { CA1: 'zero', CA2: 'zero', EXAM: 'zero' },
};

const ngMarks = (ca1: string, ca2: string, exam: string): readonly SchemeMark[] => [
  { slot: 'CA1', assessment: 'CA1', score: ca1, max_score: '20', status: 'present' },
  { slot: 'CA2', assessment: 'CA2', score: ca2, max_score: '20', status: 'present' },
  { slot: 'EXAM', assessment: 'EXAM', score: exam, max_score: '60', status: 'present' },
];

const richScheme: SchemeDefinition = {
  code: 'rich',
  slots: [
    { code: 'CA', multi: true, combine: 'mean', scale_to: '40' },
    { code: 'EXAM', max: '60' },
  ],
  learning_area_score: { op: 'sum', of: ['CA', 'EXAM'], out_of: '100' },
  component_policy: { papers: 'weighted', out_of: '20', weights: { P1: '1', P2: '1' } },
  missing: { CA: 'zero', EXAM: 'exclude' },
  rounding: [{ stage: 'learning_area_score', precision: 2, mode: 'half_up' }],
};

const STATUSES: readonly MarkStatus[] = ['present', 'absent', 'incomplete', 'exempt', 'malpractice'];

function markOf(
  slot: string,
  assessment: string,
  max: number,
  component?: string
): fc.Arbitrary<SchemeMark> {
  const base = {
    slot,
    assessment,
    ...(component === undefined ? {} : { component }),
    max_score: String(max),
  };
  return fc.tuple(fc.constantFrom(...STATUSES), scoreOf(max)).map(([status, score]) =>
    status === 'present'
      ? { ...base, score, status }
      : { ...base, status }
  );
}

const richMarks: fc.Arbitrary<readonly SchemeMark[]> = fc.tuple(
  markOf('CA', 'CA1', 20, 'P1'),
  markOf('CA', 'CA1', 20, 'P2'),
  markOf('CA', 'CA2', 20, 'P1'),
  markOf('CA', 'CA2', 20, 'P2'),
  markOf('EXAM', 'EXAM', 60)
).map((marks) => marks);

function shuffled<T>(items: readonly T[], keys: readonly number[]): T[] {
  return items
    .map((item, index) => ({ item, key: keys[index] ?? index, index }))
    .sort((left, right) => left.key - right.key || left.index - right.index)
    .map((entry) => entry.item);
}

describe('the total stays within its maximum', () => {
  it('never exceeds out_of and keeps every counted slot within its weight', () => {
    fc.assert(
      fc.property(scoreOf(20), scoreOf(20), scoreOf(60), (ca1, ca2, exam) => {
        const result = resultOf({ scheme: ngScheme, marks: ngMarks(ca1, ca2, exam) });

        expect(result.status).toBe('complete');
        expect(compareExact(totalOf(result), mustExact(result.out_of))).toBeLessThanOrEqual(0);
        expect(compareExact(mustExact(result.percent), mustExact('100'))).toBeLessThanOrEqual(0);

        for (const slot of result.slots) {
          if (slot.outcome !== 'counted') continue;
          expect(compareExact(mustExact(slot.fraction), mustExact('1'))).toBeLessThanOrEqual(0);
          expect(compareExact(mustExact(slot.contribution), mustExact(slot.weight))).toBeLessThanOrEqual(0);
        }
      }),
      OPTIONS
    );
  });
});

describe('order is irrelevant', () => {
  it('produces the same result when the marks are reordered', () => {
    fc.assert(
      fc.property(richMarks, fc.array(fc.integer({ min: 0, max: 1000 }), { minLength: 5, maxLength: 5 }), (marks, keys) => {
        const straight = resultOf({ scheme: richScheme, marks });
        const reordered = resultOf({ scheme: richScheme, marks: shuffled(marks, keys) });

        expect(JSON.stringify(reordered)).toBe(JSON.stringify(straight));
      }),
      OPTIONS
    );
  });
});

describe('scaling is monotonic', () => {
  it('never lowers the total when one raw score rises', () => {
    fc.assert(
      fc.property(
        fc.integer({ min: 0, max: 2000 }),
        scoreOf(20),
        scoreOf(60),
        fc.integer({ min: 0, max: 2000 }),
        (ca1, ca2, exam, rise) => {
          const before = totalOf(resultOf({ scheme: ngScheme, marks: ngMarks(hundredths(ca1), ca2, exam) }));
          const after = totalOf(
            resultOf({ scheme: ngScheme, marks: ngMarks(hundredths(Math.min(2000, ca1 + rise)), ca2, exam) })
          );

          expect(compareExact(after, before)).toBeGreaterThanOrEqual(0);
        }
      ),
      OPTIONS
    );
  });
});

describe('the trace replays into the result', () => {
  it('reproduces every slot and the total from the marks alone', () => {
    fc.assert(
      fc.property(richMarks, (marks) => {
        const result = resultOf({ scheme: richScheme, marks });
        const replayed = replaySchemeTrace(result.trace);

        expect(replayed.total).toBe(result.total);
        expect(replayed.percent).toBe(result.percent);
        for (const slot of result.slots) {
          expect(replayed.slots.get(slot.slot)).toEqual({
            fraction: slot.fraction,
            contribution: slot.contribution,
          });
        }
      }),
      OPTIONS
    );
  });

  it('is deterministic: identical inputs serialise identically', () => {
    fc.assert(
      fc.property(richMarks, (marks) => {
        expect(JSON.stringify(resultOf({ scheme: richScheme, marks }))).toBe(
          JSON.stringify(resultOf({ scheme: richScheme, marks }))
        );
      }),
      OPTIONS
    );
  });
});

describe('exact text', () => {
  it('round-trips any decimal through parse and format', () => {
    fc.assert(
      fc.property(
        fc.integer({ min: -1_000_000_000, max: 1_000_000_000 }),
        fc.integer({ min: 0, max: 6 }),
        (value, scale) => {
          const text = decimalAt(value, scale);
          const parsed = parseExact(text);
          if (parsed === null) throw new Error(`cannot parse ${text}`);
          const again = parseExact(formatExact(parsed));
          if (again === null) throw new Error(`cannot parse ${formatExact(parsed)}`);
          expect(compareExact(again, parsed)).toBe(0);
        }
      ),
      OPTIONS
    );
  });
});
